import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.Ccn6roXv.js";const h=JSON.parse('{"title":"Security test case catalog","description":"A compact set of mutation ideas mapped to the security properties they test.","frontmatter":{"title":"Security test case catalog","description":"A compact set of mutation ideas mapped to the security properties they test.","outline":"deep"},"headers":[],"relativePath":"tanstack-start-security-test-cases.md","filePath":"tanstack-start-security-test-cases.md"}'),i={name:"tanstack-start-security-test-cases.md"};function s(l,e,d,c,n,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="security-test-case-catalog" tabindex="-1">Security test case catalog <a class="header-anchor" href="#security-test-case-catalog" aria-label="Permalink to &quot;Security test case catalog&quot;">​</a></h1><p>Use this page after you understand the tutorial path.</p><p>The goal is not to send every possible mutation. The goal is to test one security property at a time.</p><h2 id="how-to-use-this-catalog" tabindex="-1">How to use this catalog <a class="header-anchor" href="#how-to-use-this-catalog" aria-label="Permalink to &quot;How to use this catalog&quot;">​</a></h2><ol><li>Capture a normal working server function request.</li><li>Decode it into a readable value.</li><li>Choose one property to test.</li><li>Modify one thing.</li><li>Send the request.</li><li>Record which stage rejected it.</li></ol><p>For state-changing functions, use a test account and non-production data.</p><h2 id="expected-safe-outcomes" tabindex="-1">Expected safe outcomes <a class="header-anchor" href="#expected-safe-outcomes" aria-label="Permalink to &quot;Expected safe outcomes&quot;">​</a></h2><p>Safe outcomes are boring.</p><ul><li>Invalid wire data fails before validation.</li><li>Invalid input fails before the handler.</li><li>Unauthorized input fails before state changes.</li><li>Error responses do not include stack traces or internal paths.</li><li>Server state remains correct.</li></ul><h2 id="test-group-type-changes" tabindex="-1">Test group: type changes <a class="header-anchor" href="#test-group-type-changes" aria-label="Permalink to &quot;Test group: type changes&quot;">​</a></h2><p>Property tested: runtime validation.</p><p>Examples:</p><ul><li>Replace a string with <code>null</code>.</li><li>Replace a number with a string.</li><li>Replace an object with an array.</li><li>Remove a required field.</li></ul><p>Expected result: validation rejects the request before handler logic.</p><h2 id="test-group-unexpected-fields" tabindex="-1">Test group: unexpected fields <a class="header-anchor" href="#test-group-unexpected-fields" aria-label="Permalink to &quot;Test group: unexpected fields&quot;">​</a></h2><p>Property tested: narrow accepted input.</p><p>Examples:</p><ul><li>Add <code>isAdmin</code>.</li><li>Add <code>role</code>.</li><li>Add <code>accountId</code>.</li><li>Add <code>permissions</code>.</li></ul><p>Expected result: strict schemas reject the fields, or handlers ignore them completely.</p><h2 id="test-group-dangerous-property-names" tabindex="-1">Test group: dangerous property names <a class="header-anchor" href="#test-group-dangerous-property-names" aria-label="Permalink to &quot;Test group: dangerous property names&quot;">​</a></h2><p>Property tested: safe object handling.</p><p>Examples:</p><ul><li>Add <code>__proto__</code>.</li><li>Add <code>constructor</code>.</li><li>Add <code>prototype</code>.</li></ul><p>Expected result: the value is rejected or treated as inert data. It must not affect object prototypes or server state.</p><h2 id="test-group-dynamic-field-names" tabindex="-1">Test group: dynamic field names <a class="header-anchor" href="#test-group-dynamic-field-names" aria-label="Permalink to &quot;Test group: dynamic field names&quot;">​</a></h2><p>Property tested: allow-listed state changes.</p><p>Examples:</p><ul><li>Change <code>field</code> to <code>role</code>.</li><li>Change <code>field</code> to <code>isAdmin</code>.</li><li>Change <code>field</code> to a nested-looking value such as <code>profile.role</code>.</li></ul><p>Expected result: only approved field names can be updated.</p><h2 id="test-group-context-and-authority" tabindex="-1">Test group: context and authority <a class="header-anchor" href="#test-group-context-and-authority" aria-label="Permalink to &quot;Test group: context and authority&quot;">​</a></h2><p>Property tested: least authority.</p><p>Examples:</p><ul><li>Add a role-like value to request context.</li><li>Change tenant-like identifiers.</li><li>Change owner-like identifiers.</li></ul><p>Expected result: authority still comes from the server-side session or database, not from request data.</p><h2 id="test-group-error-behavior" tabindex="-1">Test group: error behavior <a class="header-anchor" href="#test-group-error-behavior" aria-label="Permalink to &quot;Test group: error behavior&quot;">​</a></h2><p>Property tested: safe error behavior.</p><p>Examples:</p><ul><li>Send a malformed value.</li><li>Trigger validation failure.</li><li>Trigger an authorization failure.</li><li>Trigger a handler-level edge case.</li></ul><p>Expected result: the caller receives only safe error information.</p><h2 id="mapping-results" tabindex="-1">Mapping results <a class="header-anchor" href="#mapping-results" aria-label="Permalink to &quot;Mapping results&quot;">​</a></h2><p>Record results with these categories:</p><ul><li><code>decode_rejected</code></li><li><code>validation_rejected</code></li><li><code>authorization_rejected</code></li><li><code>handler_error</code></li><li><code>unexpected_state_change</code></li><li><code>unexpected_success</code></li></ul><p><code>unexpected_success</code> and <code>unexpected_state_change</code> deserve the most attention.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./guide/08-security-properties.html">Security properties</a></li><li><a href="./guide/09-common-failure-patterns.html">Common failure patterns</a></li><li><a href="./guide/10-testing-mindset.html">A simple testing mindset</a></li></ul>',45)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
